from .base_command import BaseCommand
from robot.utils import timestr_to_secs
import logging
from ..exception import RpcException, BTSSMJSONRequestError
from ..rpcexecutor import RpcExecutor
from random import randint
import json


class RemoteExecutor(BaseCommand):
    def __init__(self, rpc_port, config, rpc_session):
        super(RemoteExecutor, self).__init__()
        self._port = rpc_port
        self._is_connected = False
        self._config = config
        self._log = logging.getLogger(__name__)
        self.rpc_session = rpc_session
        self._setup_btssm_exception = None
        self._rpc_timeout = self._convert_to_secs(self._config.timeout)

    def execute_command(self, operation, params, filename=None, filepath=None, log_path=None, trs_ip=None, host_ip=None, flags=None, **kwargs):
        """ Execute remote tool command
        :param string operation:  Remote Tool to be executed
        :param dict   params:     Parameters needed for the CLI tool command
        :param string filepath:   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :param string filename:   Filename of the file. If None, default filename will be used
        :param list   flags:      Flags to be added
        :return: Path to collected file
        :rtype: list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used
        """
        flags = [] if flags is None else flags
        check_for_errors = kwargs.get('check_for_errors', True)
        return self._run_json_cmd(operation=operation, flags=flags, params=params, filename=filename, filepath=filepath,
                                  trs_ip=trs_ip, check_for_errors=check_for_errors)

    def execute_swupdate(self, operation, params, flags=None, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute swupdate tool operation
        :param string operation:  CLI tool operation used (i.e. swupdate)
        :param dict   params:     Parameters needed for the CLI tool command
        :param list   flags:      Optional parameters to be added( i.e. waitforreset)
        :param string filename:   Filename of the file. If None, default filename will be used
        :param string filepath:   Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :param string trs_ip:     TRS_IP needed
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used
        """
        flags = [] if flags is None else flags
        params['targetbd'] = self.rpc_session.executor.put_file(params['targetbd'], self.rpc_session.temp_dir)
        check_for_errors = kwargs.get('check_for_errors', True)
        return self._run_json_cmd(operation=operation, flags=flags, params=params, filename=filename,
                                  filepath=filepath, trs_ip=trs_ip, check_for_errors=check_for_errors)

    def execute_commissioning(self, operation, params, flags=None, filename=None, filepath=None, trs_ip=None, **kwargs):
        """ Execute commissioning tool operation
        :param string operation: tool operation used (i.e. swupdate)
        :param dict   params:    Parameters needed for the CLI tool command
        :param list   flags:     Optional parameters to be added( i.e. waitforreset)
        :param string filename:  Filename of the file. If None, default filename will be used
        :param string filepath:  Path to file that was specified for BTSCommandLineTools. If None, log_path in setup will be used
        :param string trs_ip:     TRS_IP needed
        :return: Path to collected file
        :rtype list

        **kwarg values:
        :param string   alias:  used to distinguish multiple library setup. Defaults to default
        :param integer timeout: timeout to be used
        """
        flags = [] if flags is None else flags
        params = self._get_commissioning_params(params, self.rpc_session)
        check_for_errors = kwargs.get('check_for_errors', True)
        return self._run_json_cmd(operation=operation, flags=flags, params=params, filename=filename,
                                  filepath=filepath, trs_ip=trs_ip, check_for_errors=check_for_errors)

    def set_setup_btssm_exception(self, exc):
        """ Sets the _setup_btssm_exception

        :param Exception exc: Exception raised from the remote tool thread
        """
        self._setup_btssm_exception = exc

    def get_config(self):
        """ Returns config data
        :return config stored
        :rtype: dict
        """
        return self._config

    def _run_json_cmd(self, operation, flags, params, filename=None, filepath=None, trs_ip=None, check_for_errors=True):
        request = self._build_json_request(method=operation, params=params, flags=flags)
        self._set_bts_connection_status(operation)
        self._log.debug("CONNECTION STATUS:{}".format(self._is_connected))
        if not self._is_connected and operation not in ('quit', 'disconnect'):
            self._create_connection_request(params=params, flags=flags)
            self._execute_request(request, check_for_errors=check_for_errors)
            self._create_disconnect_request(params=params, flags=flags)
        else:
            self._execute_request(request, check_for_errors=check_for_errors)
        return self._path_to_collected_file(option=flags, executor=self.rpc_session.executor, log_path=self._config.log_path, filename=filename,
                                            filepath=filepath, trs_ip=trs_ip, host_ip=self.rpc_session.executor._ssh_conn_params.get('host'))

    def _set_bts_connection_status(self, operation):
        if operation == 'connect':
            self._is_connected = True
        elif operation == 'disconnect':
            self._is_connected = False

    def _create_connection_request(self, params, flags):
        self._set_bts_connection_status('connect')
        parameters = {'ne': params['ne'], 'pw': params['pw'], 'timeout': params['timeout']}
        request = self._build_json_request('connect', parameters, flags)
        return self._execute_request(request)

    def _create_disconnect_request(self, params, flags):
        parameters = {'ne': params['ne'], 'pw': params['pw'], 'timeout': params['timeout']}
        request = self._build_json_request('disconnect', parameters, flags)
        self._set_bts_connection_status(operation='disconnect')
        return self._execute_request(request)

    def _execute_request(self, request, check_for_errors=True):
        with RpcExecutor(self._port, timeout=self._rpc_timeout) as rpc_executor:
            try:
                return rpc_executor.execute_request(request=request, check_for_errors=check_for_errors)
            except (BTSSMJSONRequestError, RpcException) as e:
                self._collect_cli_error_log_files(self._config, self.rpc_session)
                raise e
        if self._setup_btssm_exception:
            self._collect_cli_error_log_files(self._config, self.rpc_session)
            raise self._setup_btssm_exception[1]

    def _build_json_request(self, method, params, flags=None):
        if flags:
            for flag in flags:
                params[flag] = ''
        request_dict = {'id': randint(1000, 9999), 'method': method, 'params': params, 'jsonrpc': '2.0'}
        return json.dumps(request_dict) + '\n'

    def _convert_to_secs(self, provided_time):
        return provided_time if provided_time is None else int(timestr_to_secs(provided_time))
